import * as React from 'react';
import { ChevronDown, ChevronLeft, ChevronRight } from 'lucide-react';
import { buttonVariants } from '../../../ui/actions/button';
import { cn } from '../../../../lib/utils';
import { toUTCDate, toDateOrUndefined } from '../utils';
import type { DateValue } from '../types';

const YEAR_RANGE = 20;

type Month = {
  number: number;
  name: string;
};

const MONTHS: Month[][] = [
  [
    { number: 0, name: 'Jan' },
    { number: 1, name: 'Feb' },
    { number: 2, name: 'Mar' },
    { number: 3, name: 'Apr' },
  ],
  [
    { number: 4, name: 'May' },
    { number: 5, name: 'Jun' },
    { number: 6, name: 'Jul' },
    { number: 7, name: 'Aug' },
  ],
  [
    { number: 8, name: 'Sep' },
    { number: 9, name: 'Oct' },
    { number: 10, name: 'Nov' },
    { number: 11, name: 'Dec' },
  ],
];

type MonthViewProps = {
  value: DateValue;
  onChange: (date: DateValue) => void;
  minDate?: Date;
  maxDate?: Date;
  onClose?: () => void;
};

export function MonthView({ value, onChange, minDate, maxDate, onClose }: MonthViewProps) {
  const dateValue = toDateOrUndefined(value);
  const currentYear = new Date().getFullYear();
  const [year, setYear] = React.useState<number>(dateValue?.getFullYear() ?? currentYear);

  const selectedMonth = dateValue?.getMonth();
  const selectedYear = dateValue?.getFullYear();

  const minYear = minDate?.getFullYear() ?? currentYear - YEAR_RANGE;
  const maxYear = maxDate?.getFullYear() ?? currentYear + YEAR_RANGE;

  const years = Array.from({ length: maxYear - minYear + 1 }, (_, i) => minYear + i);

  const handleMonthSelect = (monthNumber: number) => {
    const newDate = new Date(year, monthNumber, 1);
    onChange(toUTCDate(newDate));
    onClose?.();
  };

  const isMonthDisabled = (monthNumber: number): boolean => {
    if (
      maxDate &&
      (year > maxDate.getFullYear() ||
        (year === maxDate.getFullYear() && monthNumber > maxDate.getMonth()))
    ) {
      return true;
    }
    if (
      minDate &&
      (year < minDate.getFullYear() ||
        (year === minDate.getFullYear() && monthNumber < minDate.getMonth()))
    ) {
      return true;
    }
    return false;
  };

  return (
    <div className="w-[280px] p-3">
      <div className="relative flex items-center justify-center pt-1 pb-4">
        <div className="relative">
          <select
            value={year}
            onChange={(e) => setYear(Number(e.target.value))}
            className="h-7 w-24 cursor-pointer appearance-none rounded-md border border-input bg-background px-2 pr-6 text-center font-medium text-sm ring-offset-background focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
          >
            {years.map((y) => (
              <option key={y} value={y}>
                {y}
              </option>
            ))}
          </select>
          <ChevronDown className="pointer-events-none absolute top-1/2 right-1 h-4 w-4 -translate-y-1/2 opacity-50" />
        </div>
        <button
          type="button"
          onClick={() => setYear(year - 1)}
          disabled={year <= minYear}
          className={cn(
            buttonVariants({ variant: 'outline' }),
            'absolute left-1 inline-flex h-7 w-7 items-center justify-center p-0'
          )}
        >
          <ChevronLeft className="h-4 w-4 opacity-50" />
        </button>
        <button
          type="button"
          onClick={() => setYear(year + 1)}
          disabled={year >= maxYear}
          className={cn(
            buttonVariants({ variant: 'outline' }),
            'absolute right-1 inline-flex h-7 w-7 items-center justify-center p-0'
          )}
        >
          <ChevronRight className="h-4 w-4 opacity-50" />
        </button>
      </div>

      <table className="w-full border-collapse">
        <tbody>
          {MONTHS.map((monthRow, rowIndex) => (
            <tr key={`row-${rowIndex}`} className="mt-2 flex w-full">
              {monthRow.map((month) => {
                const isSelected = selectedMonth === month.number && selectedYear === year;
                const isDisabled = isMonthDisabled(month.number);

                return (
                  <td key={month.number} className="relative h-10 w-1/4 p-0 text-center text-sm">
                    <button
                      type="button"
                      onClick={() => handleMonthSelect(month.number)}
                      disabled={isDisabled}
                      className={cn(
                        buttonVariants({
                          variant: isSelected ? 'default' : 'ghost',
                        }),
                        'h-full w-full p-0 font-normal'
                      )}
                    >
                      {month.name}
                    </button>
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

MonthView.displayName = 'MonthView';

import {
  addMonths,
  addWeeks,
  addYears,
  endOfMonth,
  endOfYear,
  endOfWeek,
  startOfMonth,
  startOfYear,
  startOfWeek,
} from 'date-fns';
import type { Preset } from './types';

/**
 * Generate preset date ranges (future-oriented for forecasting)
 */
export function generatePresets(): Preset[] {
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const tomorrow = new Date(today);
  tomorrow.setDate(tomorrow.getDate() + 1);

  const next7End = new Date(today);
  next7End.setDate(next7End.getDate() + 6);

  const next30End = new Date(today);
  next30End.setDate(next30End.getDate() + 29);

  const thisMonthEnd = endOfMonth(today);

  const nextMonthStart = startOfMonth(addMonths(today, 1));
  const nextMonthEnd = endOfMonth(addMonths(today, 1));

  const thisYearEnd = endOfYear(today);

  const nextYearStart = startOfYear(addYears(today, 1));
  const nextYearEnd = endOfYear(addYears(today, 1));

  return [
    { name: 'today', label: 'Today', range: { from: today, to: today } },
    {
      name: 'tomorrow',
      label: 'Tomorrow',
      range: { from: tomorrow, to: tomorrow },
    },
    {
      name: 'next7',
      label: 'Next 7 days',
      range: { from: today, to: next7End },
    },
    {
      name: 'next30',
      label: 'Next 30 days',
      range: { from: today, to: next30End },
    },
    {
      name: 'restOfMonth',
      label: 'Rest of month',
      range: { from: today, to: thisMonthEnd },
    },
    {
      name: 'nextMonth',
      label: 'Next month',
      range: { from: nextMonthStart, to: nextMonthEnd },
    },
    {
      name: 'restOfYear',
      label: 'Rest of year',
      range: { from: today, to: thisYearEnd },
    },
    {
      name: 'nextYear',
      label: 'Next year',
      range: { from: nextYearStart, to: nextYearEnd },
    },
  ];
}

export const DEFAULT_PRESETS = generatePresets();

/**
 * Generate presets for Date mode (day granularity)
 */
export function generateDatePresets(): Preset[] {
  return generatePresets();
}

/**
 * Generate presets for Week mode (future-oriented for forecasting)
 * Uses ISO 8601 week standard: weeks start on Monday
 */
export function generateWeekPresets(): Preset[] {
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  // ISO week starts on Monday (weekStartsOn: 1)
  const weekStartsOn = 1;

  // This week: current ISO week
  const thisWeekStart = startOfWeek(today, { weekStartsOn });
  const thisWeekEnd = endOfWeek(today, { weekStartsOn });

  // Next week: upcoming ISO week
  const nextWeekStart = startOfWeek(addWeeks(today, 1), { weekStartsOn });
  const nextWeekEnd = endOfWeek(addWeeks(today, 1), { weekStartsOn });

  // Next 4 weeks: from start of current week to end of week 4 weeks ahead
  const next4WeeksStart = startOfWeek(today, { weekStartsOn });
  const next4WeeksEnd = endOfWeek(addWeeks(today, 3), { weekStartsOn });

  // Next 12 weeks: from start of current week to end of week 12 weeks ahead
  const next12WeeksStart = startOfWeek(today, { weekStartsOn });
  const next12WeeksEnd = endOfWeek(addWeeks(today, 11), { weekStartsOn });

  return [
    { name: 'thisWeek', label: 'This week', range: { from: thisWeekStart, to: thisWeekEnd } },
    { name: 'nextWeek', label: 'Next week', range: { from: nextWeekStart, to: nextWeekEnd } },
    {
      name: 'next4Weeks',
      label: 'Next 4 weeks',
      range: { from: next4WeeksStart, to: next4WeeksEnd },
    },
    {
      name: 'next12Weeks',
      label: 'Next 12 weeks',
      range: { from: next12WeeksStart, to: next12WeeksEnd },
    },
  ];
}

/**
 * Generate presets for Month mode (future-oriented for forecasting)
 */
export function generateMonthPresets(): Preset[] {
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const thisMonthStart = startOfMonth(today);
  const thisMonthEnd = endOfMonth(today);

  const nextMonthStart = startOfMonth(addMonths(today, 1));
  const nextMonthEnd = endOfMonth(addMonths(today, 1));

  const next3MonthsEnd = endOfMonth(addMonths(today, 2));
  const next6MonthsEnd = endOfMonth(addMonths(today, 5));
  const next12MonthsEnd = endOfMonth(addMonths(today, 11));

  const thisYearEnd = endOfYear(today);

  return [
    { name: 'thisMonth', label: 'This month', range: { from: thisMonthStart, to: thisMonthEnd } },
    { name: 'nextMonth', label: 'Next month', range: { from: nextMonthStart, to: nextMonthEnd } },
    {
