        const date = new Date(year, month, 1);
        periodOptions.push({
          label: format(date, 'MMMM yyyy'),
          value: `${year}-${month}`,
        });
      }
    });
  }

  const selectedPeriodValue = baseDate
    ? `${baseDate.getFullYear()}-${viewMode === 'year' ? 0 : baseDate.getMonth()}`
    : '';

  return (
    <div className="min-w-[420px] space-y-4 p-3">
      <div className="flex items-center justify-between gap-2">
        <div className="flex gap-1">
          <button
            type="button"
            onClick={() => setViewMode('month')}
            className={cn(
              buttonVariants({ variant: viewMode === 'month' ? 'default' : 'outline' }),
              'h-8 px-3 text-xs'
            )}
          >
            Month
          </button>
          <button
            type="button"
            onClick={() => setViewMode('year')}
            className={cn(
              buttonVariants({ variant: viewMode === 'year' ? 'default' : 'outline' }),
              'h-8 px-3 text-xs'
            )}
          >
            Year
          </button>
        </div>
        <button
          type="button"
          onClick={handleGoToToday}
          className={cn(buttonVariants({ variant: 'outline' }), 'h-8 px-2')}
          title="Today"
        >
          <Calendar className="h-4 w-4" />
        </button>
      </div>

      <div className="flex items-center justify-between gap-2">
        <button
          type="button"
          onClick={() => handlePeriodChange(-1)}
          className={cn(buttonVariants({ variant: 'outline' }), 'h-8 px-2')}
        >
          <ChevronLeft className="h-4 w-4 opacity-50" />
        </button>
        <div className="relative w-[200px]">
          <select
            value={selectedPeriodValue}
            onChange={(e) => handleMonthSelect(e.target.value)}
            className="h-8 max-h-60 w-full cursor-pointer appearance-none rounded-md border border-input bg-background py-1 pr-8 pl-3 text-sm ring-offset-background focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
          >
            {periodOptions.map((option) => (
              <option key={option.value} value={option.value}>
                {option.label}
              </option>
            ))}
          </select>
          <ChevronDown className="pointer-events-none absolute top-1/2 right-2 h-4 w-4 -translate-y-1/2 opacity-50" />
        </div>
        <button
          type="button"
          onClick={() => handlePeriodChange(1)}
          className={cn(buttonVariants({ variant: 'outline' }), 'h-8 px-2')}
        >
          <ChevronRight className="h-4 w-4 opacity-50" />
        </button>
      </div>

      <div
        className={cn(
          'grid gap-2',
          viewMode === 'year'
            ? 'max-h-[250px] overflow-y-auto sm:grid-cols-3 xl:grid-cols-3'
            : 'sm:grid-cols-3 xl:grid-cols-3'
        )}
      >
        {weeks.map(({ index, weekOfYear, start, end }) => {
          const disabled = isWeekDisabled(start, end);
          const isSelected = isWeekSelected(start);
          const formattedRange = `${format(start, 'MMM d')} - ${format(end, 'MMM d')}`;

          return (
            <button
              key={`${start.toISOString()}-${end.toISOString()}`}
              type="button"
              disabled={disabled}
              onClick={() => handleWeekClick(start)}
              className={cn(
                'relative',
                'flex',
                'h-14',
                'items-center',
                'justify-between',
                'px-3',
                'transition-colors',
                'disabled:cursor-not-allowed',
                'disabled:opacity-50',
                'focus-visible:outline-none',
                'focus-visible:ring-2',
                'focus-visible:ring-ring',
                'focus-visible:ring-offset-2',
                'overflow-hidden',
                'rounded-md',
                // Border and background styling
                isSelected && 'border-2 border-primary bg-primary/5 text-primary',
                !isSelected && 'border border-input hover:border-primary/50 hover:bg-primary/5'
              )}
            >
              <div className="flex flex-col text-left">
                <span className="font-medium text-muted-foreground text-xs">
                  {viewMode === 'year' ? `Week ${weekOfYear}` : `Week ${index}`}
                </span>
                <span className="font-semibold text-sm">{formattedRange}</span>
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
}

WeekView.displayName = 'WeekView';

import * as React from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { buttonVariants } from '../../../ui/actions/button';
import { cn } from '../../../../lib/utils';
import { generateYears, toUTCDate, toDateOrUndefined } from '../utils';
import type { DateRange } from '../types';

type YearRangeViewProps = {
  range: DateRange;
  onRangeChange: (range: DateRange) => void;
  minDate?: Date;
  maxDate?: Date;
  onClose?: () => void;
  autoScroll?: boolean;
};

export function YearRangeView({
  range,
  onRangeChange,
  minDate,
  maxDate,
  onClose,
  autoScroll = false,
}: YearRangeViewProps) {
  const fromDate = toDateOrUndefined(range.from);
  const toDate = toDateOrUndefined(range.to);

  const currentYear = fromDate?.getFullYear() ?? new Date().getFullYear();
  const [centerYear, setCenterYear] = React.useState<number>(currentYear);
  const [selectingStart, setSelectingStart] = React.useState(true);

  const selectedYearRef = React.useRef<HTMLButtonElement>(null);
  const hasScrolled = React.useRef(false);

  // Reset scroll flag when centerYear or range changes (e.g., preset click)
  React.useEffect(() => {
    hasScrolled.current = false;
  }, [centerYear, range]);

  // Auto scroll to selected year after render
  React.useEffect(() => {
    if (autoScroll && !hasScrolled.current && selectedYearRef.current) {
      setTimeout(() => {
        selectedYearRef.current?.scrollIntoView({
          behavior: 'smooth',
          block: 'center',
        });
        hasScrolled.current = true;
      }, 100);
    }
  }, [autoScroll, fromDate, toDate, centerYear]);

  const years = generateYears(centerYear, 12);
  const fromYear = fromDate?.getFullYear();
  const toYear = toDate?.getFullYear();

  const handleYearClick = (year: number) => {
    const newDate = toUTCDate(new Date(year, 0, 1));

    if (selectingStart) {
      onRangeChange({ from: newDate, to: undefined });
      setSelectingStart(false);
    } else {
      if (!fromDate) {
        onRangeChange({ from: newDate, to: newDate });
        setSelectingStart(true);
        // Don't close - wait for second year selection
        return;
      }

      if (newDate < fromDate) {
        // If selected year is before start, swap them
        onRangeChange({ from: newDate, to: fromDate });
      } else {
        onRangeChange({ from: fromDate, to: newDate });
      }
      setSelectingStart(true);
      onClose?.();
    }
  };

  const isYearDisabled = (year: number): boolean => {
    if (maxDate && year > maxDate.getFullYear()) return true;
    if (minDate && year < minDate.getFullYear()) return true;
    return false;
  };

  const isYearInRange = (year: number): boolean => {
    if (!fromYear) return false;
    const endYear = toYear ?? fromYear;
    return year >= fromYear && year <= endYear;
  };

  const isYearSelected = (year: number): boolean => {
    return fromYear === year || toYear === year;
  };

  // Group years into rows of 4
  const yearRows: number[][] = [];
  for (let i = 0; i < years.length; i += 4) {
    yearRows.push(years.slice(i, i + 4));
  }

  return (
    <div className="w-[280px] p-3">
      <div className="relative flex items-center justify-center pt-1 pb-4">
        <div className="font-medium text-sm">
          {years[0]} - {years[years.length - 1]}
        </div>
        <button
          type="button"
          onClick={() => setCenterYear(centerYear - 12)}
          className={cn(
            buttonVariants({ variant: 'outline' }),
            'absolute left-1 inline-flex h-7 w-7 items-center justify-center p-0'
          )}
        >
          <ChevronLeft className="h-4 w-4 opacity-50" />
        </button>
        <button
          type="button"
          onClick={() => setCenterYear(centerYear + 12)}
          className={cn(
            buttonVariants({ variant: 'outline' }),
            'absolute right-1 inline-flex h-7 w-7 items-center justify-center p-0'
          )}
        >
          <ChevronRight className="h-4 w-4 opacity-50" />
        </button>
      </div>

      <table className="w-full border-collapse">
        <tbody>
          {yearRows.map((yearRow, rowIndex) => (
            <tr key={`row-${rowIndex}`} className="mt-2 flex w-full">
              {yearRow.map((year) => {
                const isSelected = isYearSelected(year);
                const isInRange = isYearInRange(year);
                const isDisabled = isYearDisabled(year);
                const isFirst = fromYear === year;
                const isLast = toYear === year;
                const isFirstSelected = isFirst;

                // Check if this is the current year
                const currentYear = new Date().getFullYear();
                const isCurrentYear = year === currentYear;

                return (
                  <td
                    key={year}
                    className={cn(
                      'relative h-10 w-1/4 p-0 text-center text-sm',
                      isInRange && !isSelected && 'bg-accent',
                      isFirst && 'rounded-l-md',
                      isLast && 'rounded-r-md'
                    )}
                  >
                    <button
                      ref={isFirstSelected ? selectedYearRef : undefined}
                      type="button"
                      onClick={() => handleYearClick(year)}
                      disabled={isDisabled}
                      className={cn(
                        buttonVariants({
                          variant: isSelected ? 'default' : 'ghost',
                        }),
                        'relative h-full w-full p-0 font-normal'
                      )}
                    >
                      {year}
                      {isCurrentYear && (
                        <span
                          className="absolute top-1 right-1 h-1.5 w-1.5 rounded-full bg-primary"
                          title="Current year"
                        />
                      )}
                    </button>
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
      </table>

      <div className="mt-2 text-center text-muted-foreground text-xs">
        {selectingStart ? 'Select start year' : 'Select end year'}
      </div>
    </div>
  );
}

YearRangeView.displayName = 'YearRangeView';

import * as React from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { buttonVariants } from '../../../ui/actions/button';
import { cn } from '../../../../lib/utils';
import { generateYears, toUTCDate, toDateOrUndefined } from '../utils';
import type { DateValue } from '../types';

type YearViewProps = {
  value: DateValue;
  onChange: (date: DateValue) => void;
  minDate?: Date;
  maxDate?: Date;
  onClose?: () => void;
};

export function YearView({ value, onChange, minDate, maxDate, onClose }: YearViewProps) {
  const dateValue = toDateOrUndefined(value);
  const currentYear = dateValue?.getFullYear() ?? new Date().getFullYear();
  const [centerYear, setCenterYear] = React.useState<number>(currentYear);

  const years = generateYears(centerYear, 12);
  const selectedYear = dateValue?.getFullYear();

  const handleYearSelect = (year: number) => {
    const newDate = new Date(year, 0, 1);
    onChange(toUTCDate(newDate));
    onClose?.();
  };

  const isYearDisabled = (year: number): boolean => {
    if (maxDate && year > maxDate.getFullYear()) return true;
    if (minDate && year < minDate.getFullYear()) return true;
    return false;
  };

  // Group years into rows of 4
  const yearRows: number[][] = [];
  for (let i = 0; i < years.length; i += 4) {
    yearRows.push(years.slice(i, i + 4));
  }

  return (
    <div className="w-[280px] p-3">
      <div className="relative flex items-center justify-center pt-1 pb-4">
        <div className="font-medium text-sm">
          {years[0]} - {years[years.length - 1]}
        </div>
        <button
          type="button"
          onClick={() => setCenterYear(centerYear - 12)}
          className={cn(
            buttonVariants({ variant: 'outline' }),
            'absolute left-1 inline-flex h-7 w-7 items-center justify-center p-0'
          )}
        >
          <ChevronLeft className="h-4 w-4 opacity-50" />
        </button>
        <button
          type="button"
          onClick={() => setCenterYear(centerYear + 12)}
          className={cn(
            buttonVariants({ variant: 'outline' }),
            'absolute right-1 inline-flex h-7 w-7 items-center justify-center p-0'
          )}
        >
          <ChevronRight className="h-4 w-4 opacity-50" />
        </button>
      </div>

      <table className="w-full border-collapse">
        <tbody>
          {yearRows.map((yearRow, rowIndex) => (
            <tr key={`row-${rowIndex}`} className="mt-2 flex w-full">
              {yearRow.map((year) => {
                const isSelected = selectedYear === year;
                const isDisabled = isYearDisabled(year);

                return (
                  <td key={year} className="relative h-10 w-1/4 p-0 text-center text-sm">
                    <button
                      type="button"
                      onClick={() => handleYearSelect(year)}
                      disabled={isDisabled}
                      className={cn(
                        buttonVariants({
                          variant: isSelected ? 'default' : 'ghost',
                        }),
                        'h-full w-full p-0 font-normal'
                      )}
                    >
                      {year}
                    </button>
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

